/* NEXORA public jobs, candidate, consultancy and employer portals. */
(() => {
  'use strict';
  const $ = (s, root=document) => root.querySelector(s);
  const esc = (v='') => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const fmt = v => v ? new Date(v).toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'}) : '—';
  const message = (txt, error=false) => {
    ['#portalMessage','#loginMessage'].forEach(selector=>{
      const el=$(selector);
      if(el){el.textContent=txt;el.style.color=error?'#a21d1d':'#4941b8';el.setAttribute('aria-live','polite');}
    });
  };
  const config=window.NEXORA_CONFIG;
  let sb=null,user=null,orgs=[],jobsCache=[],candidateCache=[];
  let candidateFormDirty=false,candidateLoadInProgress=false;
  const portal=document.body.dataset.portal;
  if(!window.supabase?.createClient||!config?.url||!config?.anonKey){message('Supabase client could not initialize. Check network access and public configuration.',true);return;}
  sb=window.supabase.createClient(config.url,config.anonKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});
  message('Connection ready. Sign in with your work email and password.');
  const errText=e=>e?.message||String(e||'Unknown error');
  async function run(fn){try{await fn();}catch(e){console.error('NEXORA portal:',e);message(errText(e),true);}}
  async function getUser(){const r=await sb.auth.getUser();if(r.error)throw r.error;user=r.data.user||null;return user;}
  async function ensureProfile(fullName=''){if(!user)throw new Error('Sign in first.');const current=await sb.from('candidate_profiles').select('user_id').eq('user_id',user.id).maybeSingle();if(current.error)throw current.error;if(!current.data){const r=await sb.from('candidate_profiles').insert({user_id:user.id,full_name:fullName||user.user_metadata?.full_name||'',profile_visibility:'private'});if(r.error)throw r.error;}}
  async function signIn(form){const f=new FormData(form);const r=await sb.auth.signInWithPassword({email:String(f.get('email')).trim(),password:String(f.get('password'))});if(r.error)throw r.error;user=r.data.user;message('Signed in. Loading your workspace…');await onSignedIn();}
  async function signOut(){const r=await sb.auth.signOut();if(r.error)throw r.error;user=null;location.reload();}
  function showWorkspace(id){const auth=$('#portalAuth');if(auth)auth.hidden=true;const w=$(id);if(w)w.hidden=false;const b=$('#portalLogout');if(b)b.hidden=false;}
  async function onSignedIn(){if(!user)await getUser();if(portal==='candidate'&&candidateLoadInProgress)return;if(portal==='candidate')candidateLoadInProgress=true;try{if(portal!=='company'){const accepted=await sb.rpc('accept_pending_memberships');if(accepted.error)console.warn('NEXORA membership auto-accept unavailable; continuing with existing memberships:',accepted.error.message||accepted.error);}if(portal==='candidate'){await ensureProfile();showWorkspace('#candidateWorkspace');await Promise.all([loadProfile(),loadCareerDetails(),loadCandidateDocuments(),loadCandidateLinks(),loadApplications(),loadCandidateRecommendedJobs(),loadSavedJobs(),loadJobAlerts()]);updateCandidateIdentity();message('Your candidate workspace is ready.');}else if(portal==='consultancy'){showWorkspace('#consultancyWorkspace');await Promise.all([loadConsultancyOrgs(),loadDiscovery(),loadConsultancyLinks(),loadConsultancyJobs()]);message('Consultancy workspace loaded. Candidate documents remain restricted until sharing is accepted.');}else if(portal==='company'){showWorkspace('#companyWorkspace');await loadEmployerOrgs();message('Employer workspace loaded.');}else if(portal==='public'){const b=$('#publicLogout');if(b)b.hidden=false;await ensureProfile(user.user_metadata?.full_name||'');message('Signed in. You can now apply for published jobs.');renderJobs();}}finally{if(portal==='candidate')candidateLoadInProgress=false;}}
  async function loadJobs(){const r=await sb.from('jobs').select('id,title,public_employer_name,slug,summary,location,country_code,employment_type,workplace_type,salary_min,salary_max,salary_currency,show_salary,closing_date,published_at').eq('status','published').or('closing_date.is.null,closing_date.gte.'+new Date().toISOString().slice(0,10)).order('published_at',{ascending:false}).limit(250);if(r.error)throw r.error;jobsCache=r.data||[];return jobsCache;}
  function jobCard(j){const salary=j.show_salary&&j.salary_min!=null?`<span class="job-pill">${esc(j.salary_currency||'KES')} ${Number(j.salary_min).toLocaleString()}${j.salary_max!=null?'–'+Number(j.salary_max).toLocaleString(): '+'}</span>`:'';const type=String(j.employment_type||'').replaceAll('_',' ').replace(/\b\w/g,x=>x.toUpperCase());const work=String(j.workplace_type||'').replaceAll('_',' ').replace(/\b\w/g,x=>x.toUpperCase());const published=j.published_at?new Date(j.published_at):null;const days=published&&!Number.isNaN(published.getTime())?Math.floor((Date.now()-published.getTime())/86400000):null;const freshness=days===0?'Today':days!==null&&days<=3?'New':published?fmt(j.published_at):'Recently posted';const summary=j.summary||'Open this vacancy to review the role overview, responsibilities and requirements.';return `<article class="job-card"><div class="job-card-main"><div class="job-card-top"><div class="job-card-heading"><button class="job-title-link" type="button" data-details="${esc(j.id)}">${esc(j.title||'Vacancy')}</button><div class="job-company">${esc(j.public_employer_name||'Employer')}</div><div class="job-pills"><span class="job-pill">${esc(j.location||'Location not specified')}</span>${type?`<span class="job-pill">${esc(type)}</span>`:''}${work?`<span class="job-pill">${esc(work)}</span>`:''}${salary}</div><div class="job-industry">${esc(work||'Employment opportunity')}</div></div></div><div class="job-status-row"><span class="job-new">${esc(freshness)} <span aria-hidden="true">✳</span></span><span class="job-date">${esc(freshness)}</span></div><div class="job-description-row"><div class="job-employer-mark" aria-hidden="true">N</div><p>${esc(summary)}</p></div></div><div class="job-card-footer"><span class="easy-apply"><span aria-hidden="true">♙</span> Easy apply</span><div class="job-actions"><button class="light" type="button" data-details="${esc(j.id)}">View full job</button><button class="primary" type="button" data-apply="${esc(j.id)}">Apply now</button></div></div></article>`;}
  async function viewJobDetails(jobId){
    if(!user){message('Sign in or create a free candidate account to view full vacancy details.',true);const auth=$('#candidateAccess');if(auth){auth.scrollIntoView({behavior:'smooth',block:'center'});$('#portalLogin')?.querySelector('input[name="email"]')?.focus({preventScroll:true});}return;}
    const listing=jobsCache.find(x=>x.id===jobId);if(!listing)return;
    const r=await sb.from('jobs').select('id,title,public_employer_name,summary,description,requirements,location,country_code,employment_type,workplace_type,salary_min,salary_max,salary_currency,show_salary,closing_date').eq('id',jobId).eq('status','published').maybeSingle();
    if(r.error)throw r.error;if(!r.data)throw new Error('This vacancy is no longer available.');const j=r.data;const modal=$('#jobModal');if(!modal)return;
    $('#jobModalEmployer').textContent=j.public_employer_name||'Employer';$('#jobModalTitle').textContent=j.title||'Vacancy';
    $('#jobModalMeta').textContent=[j.location,j.country_code,String(j.employment_type||'').replaceAll('_',' '),String(j.workplace_type||'').replaceAll('_',' ')].filter(Boolean).join(' · ');
    const salary=j.show_salary&&j.salary_min!=null?((j.salary_currency||'KES')+' '+Number(j.salary_min).toLocaleString()+(j.salary_max!=null?'–'+Number(j.salary_max).toLocaleString():'+')):'';
    $('#jobModalChips').innerHTML=[j.closing_date?'Closes '+fmt(j.closing_date):'Open until filled',salary].filter(Boolean).map(x=>'<span class="chip">'+esc(x)+'</span>').join('');
    $('#jobModalBody').textContent=(j.description||j.summary||'No additional description provided.')+'\n\nRequirements:\n'+(j.requirements||'Please review the role details with the employer.');$('#modalApply').dataset.apply=j.id;modal.classList.add('open');
  }
  async function renderJobs(){const el=$('#publicJobs');if(!el)return;try{await loadJobs();const q=($('#jobSearch')?.value||'').toLowerCase().trim(),locationTerm=($('#jobLocation')?.value||'').toLowerCase().trim(),type=$('#jobType')?.value||'all',workplace=$('#jobWorkplace')?.value||'all';const list=jobsCache.filter(j=>(!locationTerm||[j.location,j.country_code,j.workplace_type].some(v=>String(v||'').toLowerCase().includes(locationTerm)))&&(type==='all'||j.employment_type===type)&&(workplace==='all'||j.workplace_type===workplace)&&(!q||[j.title,j.summary,j.location,j.public_employer_name].some(v=>String(v||'').toLowerCase().includes(q))));el.innerHTML=list.length?list.map(jobCard).join(''):'<div class="empty">No matching published vacancies at the moment. Try a different search.</div>';}catch(e){el.innerHTML=`<div class="empty">Could not load vacancies: ${esc(errText(e))}. Confirm Migration 003 has been applied.</div>`;}}
  async function apply(jobId){if(!user){message('Sign in or create a candidate account before applying.',true);$('#candidateAccess')?.scrollIntoView({behavior:'smooth'});return;}await ensureProfile();const r=await sb.from('job_applications').insert({job_id:jobId,candidate_id:user.id,status:'submitted'});if(r.error){if(r.error.code==='23505')throw new Error('You have already applied for this vacancy.');throw r.error;}message('Application submitted successfully.');if(portal==='candidate'){await loadApplications();}alert('Application submitted. You can track it in the Candidate Portal.');}
  async function loadProfile(){const r=await sb.from('candidate_profiles').select('*').eq('user_id',user.id).single();if(r.error)throw r.error;const f=$('#candidateProfile');if(!f)return;if(candidateFormDirty){console.info('Skipped profile reload because the candidate has unsaved edits.');return;}for(const [k,v] of Object.entries(r.data)){const el=f.elements.namedItem(k);if(!el)continue;if(el.type==='checkbox')el.checked=!!v;else if(k==='skills')el.value=(Array.isArray(v)?v:String(v||'').split(',')).join(', ');else if(v!=null)el.value=v;}updateProfileCompletion(r.data);updateCandidateIdentity(r.data);}
  async function saveProfile(form,options={}){const f=new FormData(form);const values={user_id:user.id,full_name:String(f.get('full_name')||'').trim(),phone:String(f.get('phone')||'').trim()||null,headline:String(f.get('headline')||'').trim()||null,location:String(f.get('location')||'').trim()||null,country_code:String(f.get('country_code')||'KE'),summary:String(f.get('summary')||'').trim()||null,skills:String(f.get('skills')||'').split(',').map(x=>x.trim()).filter(Boolean),experience_years:f.get('experience_years')?Number(f.get('experience_years')):null,profile_visibility:String(f.get('profile_visibility')||'private'),consultancy_discovery_opt_in:f.get('consultancy_discovery_opt_in')==='on',completed_profile:!!String(f.get('full_name')||'').trim()&&!!String(f.get('headline')||'').trim()};if(!values.full_name)throw new Error('Full name is required. Your existing profile has not been cleared.');if(!values.headline)throw new Error('Professional headline is required. Your existing profile has not been cleared.');const r=await sb.from('candidate_profiles').upsert(values,{onConflict:'user_id'});if(r.error)throw r.error;const verified=await sb.from('candidate_profiles').select('full_name,headline,phone,location,summary,skills').eq('user_id',user.id).single();if(verified.error)throw verified.error;if(verified.data.full_name!==values.full_name||verified.data.headline!==values.headline||JSON.stringify(verified.data.skills||[])!==JSON.stringify(values.skills))throw new Error('Profile save could not be verified in the database. Your form has been kept on screen; please retry.');if(!options.skipDiscovery){try{if(values.consultancy_discovery_opt_in&&values.profile_visibility==='marketplace'){const card=await sb.from('candidate_discovery_cards').upsert({candidate_id:user.id,display_name:values.full_name,headline:values.headline,location:values.location,country_code:values.country_code,skills:values.skills,experience_years:values.experience_years,consent_enabled:true,updated_at:new Date().toISOString()},{onConflict:'candidate_id'});if(card.error)throw card.error;}else{const card=await sb.from('candidate_discovery_cards').delete().eq('candidate_id',user.id);if(card.error)throw card.error;}}catch(cardError){console.warn('Profile saved, but consultancy discovery update did not complete:',cardError);}}updateProfileCompletion(values);updateCareerCompleteness();updateCandidateIdentity(values);if(!options.keepDirty)candidateFormDirty=false;if(!options.silent)message('Profile saved and verified in your account. Consultancy discovery is '+(values.consultancy_discovery_opt_in&&values.profile_visibility==='marketplace'?'enabled by your consent.':'off.'));return values;}
  async function uploadCandidateDocument(form){const f=new FormData(form),file=f.get('file');if(!(file instanceof File)||!file.size)throw new Error('Choose a file to upload.');if(file.size>10*1024*1024)throw new Error('Files must be 10 MB or smaller.');const allowed=['application/pdf','application/msword','application/vnd.openxmlformats-officedocument.wordprocessingml.document','image/jpeg','image/png'];if(!allowed.includes(file.type))throw new Error('Allowed formats: PDF, DOC, DOCX, JPG and PNG.');const clean=file.name.replace(/[^a-zA-Z0-9._-]+/g,'_');const path=`${user.id}/${crypto.randomUUID()}-${clean}`;const up=await sb.storage.from('candidate-private-documents').upload(path,file,{contentType:file.type,upsert:false});if(up.error)throw up.error;const ins=await sb.from('candidate_documents').insert({candidate_id:user.id,document_type:f.get('document_type'),file_name:file.name,storage_path:path,mime_type:file.type,file_size_bytes:file.size});if(ins.error){await sb.storage.from('candidate-private-documents').remove([path]);throw ins.error;}form.reset();await loadCandidateDocuments();message('Document uploaded to private storage.');}
  async function loadCandidateDocuments(){const el=$('#candidateDocuments');if(!el)return;const r=await sb.from('candidate_documents').select('id,file_name,document_type,review_status,created_at').eq('candidate_id',user.id).order('created_at',{ascending:false});if(r.error)throw r.error;const docs=r.data||[];el.innerHTML=docs.map(d=>`<div class="row"><div class="rowmain"><strong>${esc(d.file_name)}</strong><small>${esc(d.document_type)} · ${esc(d.review_status)} · Uploaded ${fmt(d.created_at)}</small></div><button class="btn ghost small" data-cv-download="${esc(d.id)}">Download</button></div>`).join('')||'<div class="empty"><b>No documents uploaded yet</b>Upload your CV to start building your profile.</div>';if($('#documentCount'))$('#documentCount').textContent=docs.length;updateCareerCompleteness();if($('#documentListCount'))$('#documentListCount').textContent=docs.length+' file'+(docs.length===1?'':'s');}
  async function downloadDocument(id){const r=await sb.from('candidate_documents').select('storage_path,file_name').eq('id',id).single();if(r.error)throw r.error;const signed=await sb.storage.from('candidate-private-documents').createSignedUrl(r.data.storage_path,60,{download:r.data.file_name});if(signed.error)throw signed.error;window.open(signed.data.signedUrl,'_blank','noopener,noreferrer');}
  async function loadCandidateLinks(){const el=$('#candidateLinksList');if(!el)return;const r=await sb.from('candidate_consultancy_links').select('id,consultancy_organization_id,status,candidate_consent_at,created_at,organizations(name,website_url,verification_status)').eq('candidate_id',user.id).order('created_at',{ascending:false});if(r.error)throw r.error;const links=r.data||[];el.innerHTML=links.map(x=>`<div class="row"><div class="rowmain"><strong>${esc(x.organizations?.name||'HR consultancy')}</strong><small>${esc(x.organizations?.verification_status||'unverified')} · ${esc(x.status)} · ${fmt(x.created_at)}</small></div>${x.organizations?.website_url?`<a href="${esc(x.organizations.website_url)}" target="_blank" rel="noopener" class="btn ghost small">Website ↗</a>`:''}${x.status==='pending'?`<div class="formactions"><button class="btn small" data-link-action="accept" data-id="${esc(x.id)}">Accept sharing</button><button class="btn ghost small" data-link-action="decline" data-id="${esc(x.id)}">Decline</button></div>`:''}${x.status==='accepted'?`<button class="btn ghost small" data-link-action="revoke" data-id="${esc(x.id)}">Revoke access</button>`:''}</div>`).join('')||'<div class="empty"><b>No sharing requests</b>Verified consultancies may request access. You can accept, decline or revoke access at any time.</div>';}
  async function loadApplications(){const el=$('#candidateApplicationsList');if(!el)return;const r=await sb.from('job_applications').select('id,job_id,status,created_at,jobs(title,public_employer_name,location)').eq('candidate_id',user.id).order('created_at',{ascending:false});if(r.error)throw r.error;const apps=r.data||[];el.innerHTML=apps.map(a=>`<div class="row"><div class="rowmain"><strong>${esc(a.jobs?.title||'Vacancy')}</strong><small>${esc(a.jobs?.public_employer_name||'Employer')} · ${esc(a.jobs?.location||'Location not specified')} · Applied ${fmt(a.created_at)}</small><div style="margin-top:7px"><span class="tag ${['shortlisted','interview','offered','hired'].includes(a.status)?'green':a.status==='rejected'?'amber':''}">${esc(a.status.replaceAll('_',' '))}</span></div></div>${a.status!=='withdrawn'&&a.status!=='hired'&&a.status!=='rejected'?`<button class="btn ghost small" data-withdraw="${esc(a.id)}">Withdraw</button>`:''}</div>`).join('')||'<div class="empty"><b>No applications yet</b>Explore published jobs and apply when you find the right opportunity.</div>';if($('#applicationCount'))$('#applicationCount').textContent=apps.length;if($('#applicationListCount'))$('#applicationListCount').textContent=apps.length+' application'+(apps.length===1?'':'s');if($('#applicationTip'))$('#applicationTip').textContent=apps.filter(a=>!['withdrawn','rejected'].includes(a.status)).length+' active or completed applications';}
  async function loadConsultancyOrgs(){const r=await sb.from('organization_members').select('organization_id,role,status').eq('user_id',user.id).eq('status','active');if(r.error)throw r.error;const ids=(r.data||[]).map(x=>x.organization_id);if(!ids.length)throw new Error('No active organization membership found. Ask NEXORA to assign your account to an active consultancy.');const o=await sb.from('organizations').select('id,name,organization_type,status,verification_status').in('id',ids).eq('organization_type','consultancy');if(o.error)throw o.error;orgs=o.data||[];if(!orgs.length)throw new Error('Your account is not assigned to an HR consultancy organization.');if(orgs.every(x=>x.status!=='active'||x.verification_status!=='verified'))message('Your consultancy organization must be active and verified before candidate matching.');}
  async function loadDiscovery(){const el=$('#consultancyCandidates');if(!el)return;const r=await sb.from('candidate_discovery_cards').select('candidate_id,display_name,headline,location,country_code,skills,experience_years,consent_enabled,updated_at').eq('consent_enabled',true).order('updated_at',{ascending:false}).limit(150);if(r.error)throw r.error;candidateCache=r.data||[];renderDiscovery();}
  function renderDiscovery(){const el=$('#consultancyCandidates');if(!el)return;const q=($('#consultancySearch')?.value||'').toLowerCase();const list=candidateCache.filter(x=>!q||[x.display_name,x.headline,x.location,(x.skills||[]).join(' ')].some(v=>String(v||'').toLowerCase().includes(q)));el.innerHTML=list.map(x=>`<div class="row"><strong>${esc(x.display_name||'Candidate')} · ${esc(x.headline||'')}</strong><span class="muted">${esc(x.location||x.country_code)} · ${x.experience_years??'—'} years · ${esc((x.skills||[]).join(', '))}</span><div class="actions">${orgs.map(o=>`<button data-request-link="${esc(x.candidate_id)}" data-org="${esc(o.id)}" ${o.status!=='active'||o.verification_status!=='verified'?'disabled':''}>Request access from ${esc(o.name)}</button>`).join('')}</div></div>`).join('')||'<p class="muted">No opted-in candidate profiles match your search.</p>';}
  async function loadConsultancyLinks(){const el=$('#consultancyLinks');if(!el)return;const ids=orgs.map(o=>o.id);if(!ids.length){el.textContent='No consultancy organizations assigned.';return;}const r=await sb.from('candidate_consultancy_links').select('id,candidate_id,consultancy_organization_id,status,created_at').in('consultancy_organization_id',ids).order('created_at',{ascending:false});if(r.error)throw r.error;el.innerHTML=(r.data||[]).map(x=>`<div class="row"><strong>Candidate ${esc(x.candidate_id)}</strong><span class="muted">${esc(x.status)} · ${fmt(x.created_at)}</span>${x.status==='pending'?'Waiting for candidate consent.':''}${x.status==='accepted'?`<button class="light" data-consultancy-revoke="${esc(x.id)}">Revoke access</button>`:''}</div>`).join('')||'<p class="muted">No requests yet.</p>';}
  async function loadConsultancyDocuments(){const el=$('#consultancyDocuments');if(!el)return;const ids=orgs.map(o=>o.id);if(!ids.length)return;const links=await sb.from('candidate_consultancy_links').select('candidate_id').in('consultancy_organization_id',ids).eq('status','accepted');if(links.error)throw links.error;const cids=[...new Set((links.data||[]).map(x=>x.candidate_id))];if(!cids.length){el.innerHTML='<p class="muted">No candidate has accepted sharing yet.</p>';return;}const r=await sb.from('candidate_documents').select('id,candidate_id,file_name,document_type,review_status,created_at').in('candidate_id',cids).order('created_at',{ascending:false});if(r.error)throw r.error;el.innerHTML=(r.data||[]).map(d=>`<div class="row"><strong>${esc(d.file_name)}</strong><span class="muted">${esc(d.document_type)} · ${esc(d.review_status)} · Candidate ${esc(d.candidate_id)}</span><button class="light" data-cv-download="${esc(d.id)}">Open securely</button></div>`).join('')||'<p class="muted">No documents shared.</p>';}
  async function loadConsultancyJobs(){const el=$('#consultancyJobs');if(!el)return;const r=await sb.from('jobs').select('id,title,public_employer_name,location,country_code,employment_type,closing_date').eq('status','published').order('published_at',{ascending:false}).limit(100);if(r.error)throw r.error;el.innerHTML=(r.data||[]).map(j=>`<div class="row"><strong>${esc(j.title)} · ${esc(j.public_employer_name)}</strong><span class="muted">${esc(j.location||j.country_code)} · ${esc(j.employment_type)} · closes ${fmt(j.closing_date)}</span></div>`).join('')||'<p class="muted">No published jobs available.</p>';}
  async function loadEmployerOrgs(){const m=await sb.from('organization_members').select('organization_id,role,status').eq('user_id',user.id).eq('status','active');if(m.error)throw m.error;const ids=(m.data||[]).filter(x=>['owner','hr_manager','recruiter'].includes(x.role)).map(x=>x.organization_id);if(!ids.length)throw new Error('No active employer membership is assigned to this account. Ask the NEXORA administrator to assign your role.');const r=await sb.from('organizations').select('id,name,status,verification_status,organization_type').in('id',ids).eq('organization_type','company');if(r.error)throw r.error;orgs=r.data||[];const select=$('#employerOrganization');select.innerHTML=orgs.map(o=>`<option value="${esc(o.id)}">${esc(o.name)}${o.status!=='active'?' (suspended)':''}</option>`).join('');select.addEventListener('change',()=>loadEmployerJobs().catch(e=>message(errText(e),true)));await loadEmployerJobs();}
  async function loadEmployerJobs(){const orgId=$('#employerOrganization')?.value;const o=orgs.find(x=>x.id===orgId);$('#organizationStatus').textContent=o?`Status: ${o.status} · Verification: ${o.verification_status}`:'';const r=await sb.from('jobs').select('id,title,status,location,created_at,closing_date').eq('organization_id',orgId).order('created_at',{ascending:false});if(r.error)throw r.error;$('#employerJobs').innerHTML=(r.data||[]).map(j=>`<div class="row"><strong>${esc(j.title)}</strong><span class="muted">${esc(j.status)} · ${esc(j.location||'')} · ${fmt(j.created_at)}</span></div>`).join('')||'<p class="muted">No vacancies created yet.</p>';await loadEmployerApplications(orgId,r.data||[]);}
  async function loadEmployerApplications(orgId,jobs){const el=$('#employerApplications');if(!el)return;const ids=jobs.map(j=>j.id);if(!ids.length){el.textContent='Create a vacancy to start receiving applications.';return;}const r=await sb.from('job_applications').select('id,job_id,candidate_id,status,created_at,cover_letter,jobs(title)').in('job_id',ids).order('created_at',{ascending:false});if(r.error)throw r.error;el.innerHTML=(r.data||[]).map(a=>`<div class="row"><strong>${esc(a.jobs?.title||'Vacancy')}</strong><span class="muted">Candidate ${esc(a.candidate_id)} · ${fmt(a.created_at)} · ${esc(a.status)}</span><p>${esc(a.cover_letter||'No cover letter')}</p><div class="actions">${['under_review','shortlisted','interview','offered','hired','rejected'].filter(x=>x!==a.status).map(x=>`<button class="light" data-application-status="${esc(a.id)}" data-next="${x}">${x.replace('_',' ')}</button>`).join('')}</div></div>`).join('')||'<p class="muted">No applications received yet.</p>';}
  async function createJob(form){const orgId=$('#employerOrganization').value,o=orgs.find(x=>x.id===orgId);if(!o)throw new Error('Choose an organization.');if(o.status!=='active'||o.verification_status!=='verified')throw new Error('The organization must be active and verified before publishing recruitment. Contact NEXORA Super Admin.');const f=new FormData(form),title=String(f.get('title')).trim(),slug=title.toLowerCase().normalize('NFKD').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,100)+'-'+crypto.randomUUID().slice(0,8);const r=await sb.from('jobs').insert({organization_id:orgId,created_by:user.id,title,slug,public_employer_name:o.name,summary:f.get('summary'),description:f.get('description'),requirements:f.get('requirements')||'',location:f.get('location')||null,country_code:'KE',employment_type:f.get('employment_type'),workplace_type:f.get('workplace_type'),salary_min:f.get('salary_min')?Number(f.get('salary_min')):null,salary_max:f.get('salary_max')?Number(f.get('salary_max')):null,show_salary:f.get('show_salary')==='on',closing_date:f.get('closing_date')||null,status:'pending_review'});if(r.error)throw r.error;form.reset();await loadEmployerJobs();message('Vacancy submitted for NEXORA moderation. It is not public until approved.');}

  function updateCandidateIdentity(profile={}){const name=profile.full_name||user?.user_metadata?.full_name||user?.email?.split('@')[0]||'Candidate';const n=$('#candidateNameTop');if(n)n.textContent=name;const a=$('#candidateAvatar');if(a)a.textContent=name.trim().split(/\\s+/).slice(0,2).map(x=>x[0]||'').join('').toUpperCase()||'C';}
  function updateProfileCompletion(p={}){const fields=[p.full_name,p.phone,p.headline,p.location,p.summary,Array.isArray(p.skills)?p.skills.length:p.skills,p.experience_years];const score=Math.round(fields.filter(v=>v!==null&&v!==undefined&&String(v).trim()!=='').length/fields.length*100);if($('#profilePercent'))$('#profilePercent').textContent=score+'%';if($('#profileProgress'))$('#profileProgress').style.width=score+'%';if($('#profileTip'))$('#profileTip').textContent=score>=85?'Your profile is looking strong.':score>=55?'Good progress — add more detail to stand out.':'Add your headline, skills and summary to improve your profile.';const s=$('#profileStatus');if(s){s.textContent=p.profile_visibility==='marketplace'&&p.consultancy_discovery_opt_in?'Discoverable by consent':'Private by default';s.className='tag '+(p.profile_visibility==='marketplace'&&p.consultancy_discovery_opt_in?'green':'');}}
  async function ensureTesseract(){if(window.Tesseract)return window.Tesseract;await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/tesseract.min.js';s.onload=resolve;s.onerror=()=>reject(new Error('OCR engine could not load. Check your connection and try again.'));document.head.appendChild(s);});if(!window.Tesseract)throw new Error('OCR engine did not initialize.');return window.Tesseract;}
  async function scanPdfWithOcr(pdf){const ocr=await ensureTesseract();let text='';const maxPages=Math.min(pdf.numPages,8);for(let i=1;i<=maxPages;i++){const page=await pdf.getPage(i);const viewport=page.getViewport({scale:1.45});const canvas=document.createElement('canvas');canvas.width=Math.ceil(viewport.width);canvas.height=Math.ceil(viewport.height);const ctx=canvas.getContext('2d');await page.render({canvasContext:ctx,viewport}).promise;const result=await ocr.recognize(canvas,'eng');text+='\\n'+(result.data.text||'');canvas.width=0;canvas.height=0;}if(pdf.numPages>maxPages)text+='\\n[OCR processed the first '+maxPages+' pages only.]';return text;}
  async function extractCvText(file){const name=file.name.toLowerCase();if(file.type==='application/pdf'||name.endsWith('.pdf')){if(!window.pdfjsLib)throw new Error('PDF reader did not load. Refresh and try again.');pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';const pdf=await pdfjsLib.getDocument({data:await file.arrayBuffer()}).promise;let text='';for(let i=1;i<=pdf.numPages;i++){const page=await pdf.getPage(i);const content=await page.getTextContent();const lineMap=new Map();for(const item of content.items){const value=String(item.str||'').trim();if(!value)continue;const y=Math.round(item.transform?.[5]||0);if(!lineMap.has(y))lineMap.set(y,[]);lineMap.get(y).push({x:item.transform?.[4]||0,value});}text+='\n'+[...lineMap.entries()].sort((a,b)=>b[0]-a[0]).map(([,items])=>items.sort((a,b)=>a.x-b.x).map(x=>x.value).join(' ')).join('\n');}if(text.trim().length<35){text=await scanPdfWithOcr(pdf);if(text.trim().length<35)throw new Error('No readable text was found in this PDF. Try a clearer scan or upload a DOCX/text-based PDF.');}return text;}
    if(name.endsWith('.docx')||file.type==='application/vnd.openxmlformats-officedocument.wordprocessingml.document'){if(!window.mammoth)throw new Error('DOCX reader did not load. Refresh and try again.');const result=await mammoth.extractRawText({arrayBuffer:await file.arrayBuffer()});return result.value||'';}
    if(name.endsWith('.txt')||file.type==='text/plain')return await file.text();
    if(name.endsWith('.doc')||file.type==='application/msword')throw new Error('Legacy .DOC files cannot be scanned reliably in the browser. Open and save the CV as PDF or DOCX, then scan again.');
    if(file.type.startsWith('image/')||/\\.(jpg|jpeg|png)$/i.test(name)){const ocr=await ensureTesseract();const result=await ocr.recognize(file,'eng');return result.data.text||'';}
    throw new Error('Choose a PDF, DOCX, JPG or PNG CV to scan.');}
  function parseCvDetails(text){
    const clean=String(text||'').replace(/\r/g,'\n').replace(/[\t\u00a0]+/g,' ').replace(/[ ]{2,}/g,' ');
    const lines=clean.split('\n').map(x=>x.replace(/^[•▪●\-*\s]+/,'').trim()).filter(Boolean);
    const email=(clean.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i)||[])[0]||'';
    const phone=(clean.match(/(?:\+?\d[\d ().-]{7,}\d)/)||[])[0]?.trim()||'';
    const yearsMatch=clean.match(/(\d{1,2}(?:\.\d+)?)\s*\+?\s*(?:years?|yrs?)\s+(?:of\s+)?(?:professional\s+)?experience/i);
    const years=yearsMatch?Number(yearsMatch[1]):null;
    const skillsList=['communication','leadership','project management','customer service','sales','marketing','data analysis','excel','microsoft office','payroll','recruitment','human resources','hr management','accounting','bookkeeping','nursing','clinical care','teaching','training','research','program management','administration','operations','time management','problem solving','teamwork','javascript','react','sql','python','project planning','financial reporting','employee relations','talent acquisition','performance management','workforce planning','compliance','procurement','logistics','digital marketing','graphic design','customer relations','patient care','critical thinking','record keeping','inventory management','budgeting','quality assurance'];
    const lower=clean.toLowerCase();
    const skills=[...new Set(skillsList.filter(x=>new RegExp('(^|[^a-z])'+x.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'([^a-z]|$)','i').test(lower)))];
    const heading=/^(curriculum vitae|resume|résumé|cv|profile|contact(?: details| information)?|personal details|professional summary|summary|objective|career objective|work experience|employment history|experience|education|qualifications|skills|core skills|key skills|references|languages|certifications?|professional profile|career profile|areas of expertise|technical skills|achievements|key achievements|projects|training|interests|referees|personal statement)\s*:?$/i;
    const contact=/@|https?:|www\.|linkedin\.com|\+?\d[\d ()-]{7,}/i;
    const plausibleName=s=>s.length>=5&&s.length<=55&&!contact.test(s)&&!heading.test(s)&&!/\d{3,}/.test(s)&&!/\b(curriculum vitae|resume|professional summary|phone|email|address|nairobi|kenya|linkedin|profile)\b/i.test(s)&&s.split(/\s+/).length>=2&&s.split(/\s+/).length<=5&&/^[A-Za-zÀ-ÿ'’.-]+(?:\s+[A-Za-zÀ-ÿ'’.-]+){1,4}$/.test(s);
    const full_name=lines.slice(0,12).find(plausibleName)||'';
    const location=(clean.match(/\b(Nairobi|Mombasa|Kisumu|Nakuru|Eldoret|Thika|Nyeri|Kampala|Dar es Salaam|Kigali|Lagos|Accra|Johannesburg|Cape Town|London|Berlin)\b(?:,?\s*(Kenya|Uganda|Tanzania|Rwanda|Nigeria|Ghana|South Africa|United Kingdom|Germany))?/i)||[])[0]||'';
    const headline=lines.slice(0,18).find(x=>x!==full_name&&x.length>=8&&x.length<=100&&!contact.test(x)&&!heading.test(x)&&!/^\+?[\d ().-]+$/.test(x)&&!/[;,].*[;,].*/.test(x)&&!/(?:^|[^a-z])(?:skills|experience|education|summary|objective)(?:$|[^a-z])/i.test(x)&&!/\b(nairobi|mombasa|kisumu|nakuru|kenya|curriculum vitae|resume)\b/i.test(x))||'';
    const summaryHeader=lines.findIndex(x=>/^(professional summary|summary|profile|professional profile|career objective|objective|personal statement)\s*:?$/i.test(x));
    const sectionHeading=/^(professional summary|summary|profile|professional profile|career objective|objective|personal statement|work experience|employment history|experience|education|qualifications|skills|core skills|key skills|references|languages|certifications?|professional profile|areas of expertise|technical skills|achievements|key achievements|projects|training|interests|referees)\s*:?$/i;
    let summary='';
    if(summaryHeader>=0){const body=[];for(let i=summaryHeader+1;i<lines.length&&body.length<6;i++){if(sectionHeading.test(lines[i]))break;if(!contact.test(lines[i])&&lines[i]!==full_name)body.push(lines[i]);}summary=body.join(' ').slice(0,650);}
    if(!summary){summary=lines.filter(x=>x!==full_name&&x!==headline&&x.length>=55&&!contact.test(x)&&!heading.test(x)&&!/^[-•\d. ]+$/.test(x)&&!/[;,].*[;,].*/.test(x)).sort((a,b)=>b.length-a.length).slice(0,3).join(' ').slice(0,650);}
    return {full_name,phone,email,experience_years:years,skills,location,headline,summary,hasText:clean.trim().length>80};
  }
  async function scanCandidateCv(){const file=$('#candidateFile')?.files?.[0],status=$('#cvScanStatus'),preview=$('#cvExtractPreview'),button=$('#scanCvButton'),progress=$('#cvProgress');if(!file)throw new Error('Choose your CV file first.');if(file.size>10*1024*1024)throw new Error('Files must be 10 MB or smaller.');if(status){status.hidden=false;status.className='notice';status.textContent='Reading your CV in this browser… Your file is not uploaded by the scan action.';}if(button)button.disabled=true;if(progress)progress.style.width='22%';try{const text=await extractCvText(file);if(progress)progress.style.width='75%';if(!text.trim())throw new Error('No readable text was found. Try a text-based PDF or DOCX file.');const d=parseCvDetails(text);if(!d.hasText)throw new Error('Not enough readable CV text was found. Please check the file or enter your details manually.');const form=$('#candidateProfile');const set=(key,value)=>{const el=form?.elements.namedItem(key);if(el&&value!==''&&value!==null&&value!==undefined){if(key==='skills')el.value=Array.isArray(value)?value.join(', '):value;else el.value=value;}};['full_name','phone','location','headline','summary','experience_years','skills'].forEach(k=>set(k,d[k]));updateProfileCompletion(Object.fromEntries(['full_name','phone','location','headline','summary','experience_years','skills'].map(k=>[k,form?.elements.namedItem(k)?.value])));if(preview){preview.hidden=false;preview.innerHTML='<div class="notice success"><strong>CV scan complete — review the extracted details below before saving your profile.</strong><br>Detected: '+[d.full_name?'name':'',d.phone?'phone':'',d.email?'email in CV':'',d.skills.length?d.skills.length+' skills':'',d.experience_years!==null?'experience':''].filter(Boolean).map(esc).join(' · ')+'</div><p class="muted" style="font-size:11px">Fields have been filled in for review. No profile changes are saved until you select “Save career profile”. The email detected in your CV is not used to change your login email.</p>';}if(status){status.hidden=false;status.className='notice success';status.textContent='CV scanned successfully. Review the filled fields in Career profile, then save your profile. Upload the file separately to store it securely.';}if(progress)progress.style.width='100%';$('#candidateProfile')?.scrollIntoView({behavior:'smooth',block:'start'});}catch(e){if(status){status.hidden=false;status.className='notice error';status.textContent=e.message||String(e);}if(progress)progress.style.width='0%';throw e;}finally{if(button)button.disabled=false;}}



  function downloadCareerCv(){if(!user)throw new Error('Sign in to download your career profile.');const form=$('#candidateProfile');const val=name=>String(form?.elements.namedItem(name)?.value||'').trim();const textLines=id=>String($('#'+id)?.value||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean);const escHtml=x=>esc(x);const section=(title,items)=>items.length?'<section><h2>'+escHtml(title)+'</h2><ul>'+items.map(x=>'<li>'+escHtml(x)+'</li>').join('')+'</ul></section>':'';const name=val('full_name')||'Candidate Career Profile';const skills=val('skills').split(',').map(x=>x.trim()).filter(Boolean);const details=[['Work experience','detailExperience'],['Education','detailEducation'],['Professional associations','detailAssociations'],['Certificates & awards','detailCertificates'],['Languages','detailLanguages'],['Professional references','detailReferences'],['Projects & portfolio','detailPortfolio']].map(([title,id])=>section(title,textLines(id)));const summary=val('summary');const cover=String($('#detailCoverLetter')?.value||'').trim();const doc='<!doctype html><html><head><meta charset="utf-8"><title>'+escHtml(name)+' — Career Profile</title><style>body{font:11pt/1.5 Arial,sans-serif;color:#202a3b;max-width:800px;margin:35px auto;padding:0 24px}h1{font-size:24pt;margin:0}h2{font-size:14pt;border-bottom:1px solid #ccd2df;padding-bottom:4px;margin-top:24px}header p{margin:5px 0;color:#536078}.headline{font-size:13pt;font-weight:bold;color:#5046c8;margin-top:8px}li{margin:4px 0;white-space:pre-wrap}.summary{white-space:pre-wrap}@media print{body{margin:0 auto;padding:0 12mm}a{color:inherit}}</style></head><body><header><h1>'+escHtml(name)+'</h1><div class="headline">'+escHtml(val('headline'))+'</div><p>'+escHtml([val('phone'),user.email,val('location')].filter(Boolean).join(' · '))+'</p><p>'+escHtml(skills.length?'Skills: '+skills.join(', '):'')+'</p></header>'+(summary?'<section><h2>Professional summary</h2><p class="summary">'+escHtml(summary)+'</p></section>':'')+details.join('')+(cover?'<section><h2>Cover letter</h2><p class="summary">'+escHtml(cover)+'</p></section>':'')+'<footer><p>Generated from the candidate-provided NEXORA career profile. Please review before sharing.</p></footer><script>window.addEventListener("load",()=>setTimeout(()=>window.print(),250));<\/script></body></html>';const w=window.open('','_blank');if(!w)throw new Error('Allow pop-ups to open the printable CV, then choose Save as PDF.');w.document.open();w.document.write(doc);w.document.close();}
  function updateCareerCompleteness(){const val=id=>String($('#'+id)?.value||'').trim();const checks=[val('candidateProfile')&&!!$('#candidateProfile')?.elements.namedItem('full_name')?.value?.trim(),val('candidateProfile')&&!!$('#candidateProfile')?.elements.namedItem('headline')?.value?.trim(),val('candidateProfile')&&!!$('#candidateProfile')?.elements.namedItem('summary')?.value?.trim(),val('candidateProfile')&&!!$('#candidateProfile')?.elements.namedItem('phone')?.value?.trim(),val('candidateProfile')&&!!$('#candidateProfile')?.elements.namedItem('location')?.value?.trim(),val('candidateProfile')&&!!$('#candidateProfile')?.elements.namedItem('skills')?.value?.trim(),val('detailExperience'),val('detailEducation'),val('detailAssociations'),val('detailCertificates'),val('detailLanguages'),val('detailReferences'),val('detailCoverLetter'),val('detailPortfolio'),val('detailAvailability'),val('detailJobFunction')||val('detailLocations'),Number($('#documentCount')?.textContent||0)>0];const score=Math.round(checks.filter(Boolean).length/checks.length*100);if($('#profilePercent'))$('#profilePercent').textContent=score+'%';if($('#profileProgress'))$('#profileProgress').style.width=score+'%';if($('#profileTip'))$('#profileTip').textContent=score>=85?'Your career profile is looking strong.':score>=55?'Good progress — complete the remaining sections to stand out.':'Complete more sections to help employers understand your experience.';}
  const careerArrayFields={work_experience:'detailExperience',education:'detailEducation',associations:'detailAssociations',certificates:'detailCertificates',languages:'detailLanguages',professional_references:'detailReferences',portfolio:'detailPortfolio'};
  function linesToJson(value){return String(value||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean).map(line=>line.split('|').map(part=>part.trim()));}
  function jsonToLines(value){return (Array.isArray(value)?value:[]).map(item=>(Array.isArray(item)?item:Object.values(item||{})).filter(x=>x!==null&&x!==undefined&&String(x).trim()!=='').join(' | ')).join('\n');}
  async function loadCareerDetails(){const r=await sb.from('candidate_career_details').select('*').eq('candidate_id',user.id).maybeSingle();if(r.error)throw r.error;if(candidateFormDirty){console.info('Skipped career-section reload because the candidate has unsaved edits.');return;}const d=r.data||{};for(const [key,id] of Object.entries(careerArrayFields)){const el=$('#'+id);if(el)el.value=jsonToLines(d[key]);}const p=d.preferences||{};const map={detailAvailability:'availability',detailWorkType:'work_type',detailJobFunction:'job_function',detailIndustry:'industry',detailLocations:'preferred_locations',detailSalary:'salary_expectation',detailQualification:'qualification_level',detailGender:'gender',detailDisability:'disability_status'};for(const [id,key] of Object.entries(map)){const el=$('#'+id);if(el&&p[key]!=null)el.value=p[key];}if($('#detailDob')&&d.date_of_birth)$('#detailDob').value=d.date_of_birth;if($('#detailDisplaced'))$('#detailDisplaced').checked=!!d.internally_displaced;if($('#detailCoverLetter'))$('#detailCoverLetter').value=d.cover_letter||'';updateCareerCompleteness();}
  async function saveCareerDetails(){if(!user)throw new Error('Sign in to save your career profile.');const profileForm=$('#candidateProfile');if(profileForm&&!profileForm.reportValidity())throw new Error('Complete the required full name and professional headline in Career profile before saving everything.');if(profileForm)await saveProfile(profileForm,{skipDiscovery:true,silent:true,keepDirty:true});const preferences={availability:$('#detailAvailability')?.value||'immediately',work_type:$('#detailWorkType')?.value||'any',job_function:$('#detailJobFunction')?.value.trim()||'',industry:$('#detailIndustry')?.value.trim()||'',preferred_locations:$('#detailLocations')?.value.trim()||'',salary_expectation:$('#detailSalary')?.value?Number($('#detailSalary').value):null,qualification_level:$('#detailQualification')?.value||'',gender:$('#detailGender')?.value||'',disability_status:$('#detailDisability')?.value||''};const values={candidate_id:user.id,preferences,work_experience:linesToJson($('#detailExperience')?.value),education:linesToJson($('#detailEducation')?.value),associations:linesToJson($('#detailAssociations')?.value),certificates:linesToJson($('#detailCertificates')?.value),languages:linesToJson($('#detailLanguages')?.value),professional_references:linesToJson($('#detailReferences')?.value),portfolio:linesToJson($('#detailPortfolio')?.value),cover_letter:$('#detailCoverLetter')?.value.trim()||null,gender:preferences.gender||null,date_of_birth:$('#detailDob')?.value||null,disability_status:preferences.disability_status||null,internally_displaced:!!$('#detailDisplaced')?.checked,updated_at:new Date().toISOString()};const r=await sb.from('candidate_career_details').upsert(values,{onConflict:'candidate_id'});if(r.error)throw r.error;const verified=await sb.from('candidate_career_details').select('candidate_id,work_experience,education,associations,certificates,languages,professional_references,portfolio,preferences,cover_letter').eq('candidate_id',user.id).single();if(verified.error)throw verified.error;for(const key of ['work_experience','education','associations','certificates','languages','professional_references','portfolio'])if(JSON.stringify(verified.data[key]||[])!==JSON.stringify(values[key]||[]))throw new Error('Your career sections did not verify after saving ('+key+'). The form has been kept on screen; please retry.');candidateFormDirty=false;const status=$('#careerDetailsStatus');if(status)status.textContent='All profile details saved permanently · '+new Date().toLocaleTimeString();updateCareerCompleteness();message('Your entire career profile has been saved permanently. Your entries remain on screen.');}
  let savedJobIds=new Set();
  async function loadSavedJobs(){const r=await sb.from('candidate_saved_jobs').select('id,job_id,created_at,jobs(id,title,public_employer_name,location,employment_type,workplace_type,closing_date,summary)').eq('candidate_id',user.id).order('created_at',{ascending:false});if(r.error)throw r.error;const rows=r.data||[];savedJobIds=new Set(rows.map(x=>x.job_id));renderSavedJobs(rows);renderCandidateRecommendedJobs();}
  function renderSavedJobs(rows=[]){const el=$('#candidateSavedJobsList');if(!el)return;if($('#savedJobsCount'))$('#savedJobsCount').textContent=rows.length+' saved';el.innerHTML=rows.map(x=>{const j=x.jobs||{};return '<div class="row"><div class="rowmain"><strong>'+esc(j.title||'Vacancy')+'</strong><small>'+esc(j.public_employer_name||'Employer')+' · '+esc(j.location||'Location not specified')+' · '+esc(j.employment_type||'')+'</small></div><button class="btn ghost small" data-details="'+esc(j.id||x.job_id)+'">View job</button><button class="btn ghost small" data-unsave-job="'+esc(x.job_id)+'">Remove</button></div>';}).join('')||'<div class="empty"><b>No saved jobs yet</b>Use Save job on a vacancy to keep it here.</div>';}
  async function toggleSavedJob(jobId){if(!user)throw new Error('Sign in to save jobs.');if(savedJobIds.has(jobId)){const r=await sb.from('candidate_saved_jobs').delete().eq('candidate_id',user.id).eq('job_id',jobId);if(r.error)throw r.error;}else{const r=await sb.from('candidate_saved_jobs').insert({candidate_id:user.id,job_id:jobId});if(r.error&&r.error.code!=='23505')throw r.error;}await loadSavedJobs();message(savedJobIds.has(jobId)?'Job saved to your list.':'Saved jobs updated.');}
  async function loadJobAlerts(){const el=$('#candidateJobAlertsList');if(!el)return;const r=await sb.from('candidate_job_alerts').select('*').eq('candidate_id',user.id).order('created_at',{ascending:false});if(r.error)throw r.error;el.innerHTML=(r.data||[]).map(a=>'<div class="row"><div class="rowmain"><strong>'+esc(a.alert_name)+'</strong><small>'+esc([a.keywords,a.location,a.workplace_type==='all'?'Any arrangement':a.workplace_type,a.frequency].filter(Boolean).join(' · '))+'</small></div><span class="tag '+(a.is_active?'green':'')+'">'+(a.is_active?'Active':'Paused')+'</span><button class="btn ghost small" data-toggle-alert="'+esc(a.id)+'" data-active="'+(!a.is_active)+'">'+(a.is_active?'Pause':'Activate')+'</button><button class="btn ghost small" data-delete-alert="'+esc(a.id)+'">Delete</button></div>').join('')||'<div class="empty">No job alerts created yet.</div>';}
  async function createJobAlert(form){const f=new FormData(form);const values={candidate_id:user.id,alert_name:String(f.get('alert_name')||'My job alert').trim(),keywords:String(f.get('keywords')||'').trim()||null,location:String(f.get('location')||'').trim()||null,workplace_type:String(f.get('workplace_type')||'all'),employment_type:String(f.get('employment_type')||'all'),frequency:String(f.get('frequency')||'weekly'),is_active:true};const r=await sb.from('candidate_job_alerts').insert(values);if(r.error)throw r.error;form.reset();await loadJobAlerts();message('Job alert saved. Automated email delivery is not enabled yet; this saves and manages alert preferences.');}
  async function loadCandidateRecommendedJobs(){const el=$('#candidateRecommendedJobs');if(!el)return;try{await loadJobs();renderCandidateRecommendedJobs();}catch(e){el.innerHTML='<div class="empty"><b>Opportunities could not load</b>'+esc(errText(e))+'</div>';}}
  function renderCandidateRecommendedJobs(){const el=$('#candidateRecommendedJobs');if(!el)return;const q=($('#candidateJobSearch')?.value||'').toLowerCase().trim(),work=$('#candidateJobWorkplace')?.value||'all';const list=jobsCache.filter(j=>(work==='all'||j.workplace_type===work)&&(!q||[j.title,j.summary,j.description,j.requirements,j.location,j.public_employer_name].some(v=>String(v||'').toLowerCase().includes(q)))).slice(0,8);el.innerHTML=list.map(j=>'<article class="job"><div class="jobtop"><div><div class="muted" style="font-size:11px">'+esc(j.public_employer_name||'Employer')+' · '+esc(j.country_code||'KE')+'</div><h3>'+esc(j.title)+'</h3><p>'+esc(j.location||'Location not specified')+' · '+esc(String(j.employment_type||'').replaceAll('_',' '))+'</p></div><span class="tag">'+esc(String(j.workplace_type||'onsite'))+'</span></div><p>'+esc(j.summary||'Explore the role details and requirements.')+'</p><div class="chips">'+(j.show_salary&&j.salary_min!=null?'<span class="chip">'+esc(j.salary_currency||'KES')+' '+Number(j.salary_min).toLocaleString()+(j.salary_max!=null?'–'+Number(j.salary_max).toLocaleString():'+')+'</span>':'')+'<span class="chip">Closes '+fmt(j.closing_date)+'</span></div><button class="btn small" data-apply="'+esc(j.id)+'">Apply now →</button> <button class="btn ghost small" data-details="'+esc(j.id)+'">View details</button> <button class="btn ghost small" data-save-job="'+esc(j.id)+'">'+(savedJobIds.has(j.id)?'★ Saved':'☆ Save job')+'</button></article>').join('')||'<div class="empty"><b>No matching vacancies right now</b>Try another search or visit the public jobs marketplace.</div>';}
  document.addEventListener('submit',e=>{const f=e.target;if(f.id==='candidateLogin'||f.id==='portalLogin'){e.preventDefault();run(()=>signIn(f));}if(f.id==='candidateSignup'){e.preventDefault();run(async()=>{const fd=new FormData(f);const r=await sb.auth.signUp({email:String(fd.get('email')).trim(),password:String(fd.get('password')),options:{data:{full_name:String(fd.get('full_name')).trim(),account_type:'candidate'}}});if(r.error)throw r.error;if(r.data.session){user=r.data.user;await ensureProfile(String(fd.get('full_name')).trim());await onSignedIn();}else message('Account created. Check your email to confirm the account, then sign in.');});}if(f.id==='candidateProfile'){e.preventDefault();run(()=>saveProfile(f));}if(f.id==='candidateJobAlertForm'){e.preventDefault();run(()=>createJobAlert(f));}if(f.id==='candidateUpload'){e.preventDefault();run(()=>uploadCandidateDocument(f));}if(f.id==='jobCreate'){e.preventDefault();run(()=>createJob(f));}if(f.id==='supportTicketForm'){e.preventDefault();run(async()=>{if(!user)throw new Error('Sign in first.');const fd=new FormData(f);let organization_id=null;if(portal==='company')organization_id=$('#employerOrganization')?.value||null;if(portal==='consultancy')organization_id=orgs[0]?.id||null;const r=await sb.from('support_tickets').insert({requester_user_id:user.id,organization_id,subject:String(fd.get('subject')).trim(),description:String(fd.get('description')).trim(),category:String(fd.get('category')||'general'),priority:'normal',status:'open'});if(r.error)throw r.error;f.reset();message('Support ticket submitted. The NEXORA team can now review it.');});}});
  document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='portalLogout'||b.id==='publicLogout'){run(signOut);}if(b.id==='scanCvButton'){run(()=>scanCandidateCv());}if(b.id==='saveCareerDetails'){run(()=>saveCareerDetails());}if(b.id==='downloadCareerCv'){run(()=>downloadCareerCv());}if(b.dataset.saveJob){run(()=>toggleSavedJob(b.dataset.saveJob));}if(b.dataset.unsaveJob){run(()=>toggleSavedJob(b.dataset.unsaveJob));}if(b.dataset.toggleAlert){run(async()=>{const r=await sb.from('candidate_job_alerts').update({is_active:b.dataset.active==='true',updated_at:new Date().toISOString()}).eq('id',b.dataset.toggleAlert).eq('candidate_id',user.id);if(r.error)throw r.error;await loadJobAlerts();});}if(b.dataset.deleteAlert){run(async()=>{const r=await sb.from('candidate_job_alerts').delete().eq('id',b.dataset.deleteAlert).eq('candidate_id',user.id);if(r.error)throw r.error;await loadJobAlerts();});}if(b.id==='refreshJobs'||b.id==='consultancyRefresh'){run(()=>portal==='public'?renderJobs():portal==='consultancy'?Promise.all([loadDiscovery(),loadConsultancyLinks(),loadConsultancyDocuments()]):Promise.resolve());}if(b.dataset.apply){run(()=>apply(b.dataset.apply));}if(b.dataset.details){run(()=>viewJobDetails(b.dataset.details));}if(b.dataset.cvDownload){run(()=>downloadDocument(b.dataset.cvDownload));}if(b.dataset.linkAction){run(async()=>{const patch=b.dataset.linkAction==='accept'?{status:'accepted',candidate_consent_at:new Date().toISOString(),updated_at:new Date().toISOString()}:{status:b.dataset.linkAction==='decline'?'declined':'revoked',updated_at:new Date().toISOString()};const r=await sb.from('candidate_consultancy_links').update(patch).eq('id',b.dataset.id);if(r.error)throw r.error;await loadCandidateLinks();message('Consultancy sharing preference updated.');});}if(b.dataset.requestLink){run(async()=>{const orgId=b.dataset.org,o=orgs.find(x=>x.id===orgId);if(!o||o.verification_status!=='verified'||o.status!=='active')throw new Error('Consultancy is not active and verified.');const r=await sb.from('candidate_consultancy_links').insert({candidate_id:b.dataset.requestLink,consultancy_organization_id:orgId,status:'pending',requested_by:user.id});if(r.error){if(r.error.code==='23505')throw new Error('A request already exists for this candidate and consultancy.');throw r.error;}await loadConsultancyLinks();message('Sharing request sent. Candidate consent is required before document access.');});}if(b.dataset.consultancyRevoke){run(async()=>{const r=await sb.from('candidate_consultancy_links').update({status:'revoked',updated_at:new Date().toISOString()}).eq('id',b.dataset.consultancyRevoke);if(r.error)throw r.error;await Promise.all([loadConsultancyLinks(),loadConsultancyDocuments()]);});}if(b.dataset.withdraw){run(async()=>{const r=await sb.from('job_applications').update({status:'withdrawn',candidate_withdrawn_at:new Date().toISOString(),updated_at:new Date().toISOString()}).eq('id',b.dataset.withdraw);if(r.error)throw r.error;await loadApplications();});}if(b.dataset.applicationStatus){run(async()=>{const r=await sb.from('job_applications').update({status:b.dataset.next,reviewed_by:user.id,reviewed_at:new Date().toISOString(),updated_at:new Date().toISOString()}).eq('id',b.dataset.applicationStatus);if(r.error)throw r.error;await loadEmployerJobs();message('Application status updated.');});}});
  $('#jobSearch')?.addEventListener('input',()=>renderJobs());$('#jobLocation')?.addEventListener('input',()=>renderJobs());$('#jobType')?.addEventListener('change',()=>renderJobs());$('#jobWorkplace')?.addEventListener('change',()=>renderJobs());$('#modalApply')?.addEventListener('click',e=>{const id=e.currentTarget.dataset.apply;if(id)run(()=>apply(id));$('#jobModal')?.classList.remove('open');});$('#consultancySearch')?.addEventListener('input',renderDiscovery);$('#candidateJobSearch')?.addEventListener('input',renderCandidateRecommendedJobs);$('#candidateJobWorkplace')?.addEventListener('change',renderCandidateRecommendedJobs);
  $('#candidateProfile,#careerSections')?.addEventListener('input',()=>{candidateFormDirty=true;});$('#candidateProfile,#careerSections')?.addEventListener('change',()=>{candidateFormDirty=true;});
  $('#year')&&($('#year').textContent=new Date().getFullYear());
  if(portal==='public')renderJobs();
  sb.auth.onAuthStateChange((_event,session)=>{user=session?.user||null;if(user){setTimeout(()=>run(onSignedIn),0);}else{const w=$('#candidateWorkspace')||$('#consultancyWorkspace')||$('#companyWorkspace');if(w)w.hidden=true;const auth=$('#portalAuth');if(auth)auth.hidden=false;const b=$('#publicLogout');if(b)b.hidden=true;if(portal==='company')message('Connection ready. Sign in with your work email and password.');}});
})();
